352			t.Fatalf("blank reason, got %v", err)
353		}
354		if _, err := s.Void("nope", "x"); !errors.Is(err, ErrUnknownSample) {
355			t.Fatalf("unknown sample, got %v", err)
356		}
357	
358		// 已确认样品作废后保留结果
359		if _, err := s.Confirm("S2"); err != nil {
360			t.Fatalf("Confirm S2: %v", err)
361		}
362		v, err := s.Void("S2", "  采样瓶破损  ")
