367			t.Fatalf("voided sample should keep results, got %+v", v)
368		}
369	
370		// 待判定样品作废后不能再确认
371		if _, err := s.Void("S1", "记录错误"); err != nil {
372			t.Fatalf("Void pending: %v", err)
373		}
374		if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
375			t.Fatalf("confirm voided, got %v", err)
376		}
377	
378		// 重复作废：相同原因（去空白后）返回原记录，不同原因拒绝
379		if _, err := s.Void("S1", " 记录错误 "); err != nil {
380			t.Fatalf("same reason should return record, got %v", err)
381		}
382		if _, err := s.Void("S1", "别的原因"); !errors.Is(err, ErrVoidReasonConflict) {
383			t.Fatalf("different reason should be rejected, got %v", err)
384		}
385	
386		// 已作废样品的相同内容重报仍返回原样品，不同内容仍拒绝
387		if _, err := s.SubmitSample("S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 7}); err != nil {
388			t.Fatalf("resubmit voided identical: %v", err)
389		}
390		if _, err := s.SubmitSample("S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 8}); !errors.Is(err, ErrSampleConflict) {
391			t.Fatalf("resubmit voided different, got %v", err)
392		}
393	}
