403		mustSample(t, s, "S1", "P1", at(5, 0), Measurement{Item: "pH", Value: 7}) // 同时刻，编号升序
404		mustSample(t, s, "S3", "P1", at(8, 0), Measurement{Item: "pH", Value: 9})
405		mustSample(t, s, "S4", "P1", at(9, 0), Measurement{Item: "pH", Value: 7})
406		mustSample(t, s, "SX", "P2", at(10, 0), Measurement{Item: "pH", Value: 7})
