415		list, err := s.ListByPoint("P1")
416		if err != nil {
417			t.Fatalf("ListByPoint: %v", err)
418		}
419		ids := []string{list[0].ID, list[1].ID, list[2].ID, list[3].ID}
420		want := []string{"S4", "S3", "S1", "S2"} // 时间晚到早，同时刻编号升序
421		for i := range want {
