431		}
432		if list[0].Status != StatusVoided || list[2].Status != StatusPending {
433			t.Fatalf("statuses wrong: %+v", list)
434		}
435	
436		// 最近有效结果：跳过待判定与作废，取 S3
437		latest, ok, err := s.LatestResult("P1")
438		if err != nil || !ok || latest.ID != "S3" {
439			t.Fatalf("latest = %+v ok=%v err=%v", latest, ok, err)
440		}
441	
442		// 没有已确认且未作废的样品时明确无结果
443		if _, ok, err := s.LatestResult("P2"); err != nil || ok {
444			t.Fatalf("P2 should have no result, ok=%v err=%v", ok, err)
